test('HM-FE-001 precise capacity-busy refusal releases only this unconsumed hint for a later explicit click',async t=>{
 const stored=(a,plot='heatmap')=>{const key='cyomics:'+plot+'-render:refs:v1:'+a.o.parentMetadata.created_by;return{key,text:a.storage.getItem(key)};};
 const contextOf=d=>({project_id:d.project_id,actor_id:d.created_by,source_result_id:d.source_result_id,source_metadata_sha256:d.source_metadata_sha256,source_manifest_sha256:d.source_manifest_sha256,derived_version_id:d.derived_version_id,derived_metadata_sha256:d.derived_metadata_sha256,derived_manifest_sha256:d.derived_manifest_sha256,source_binding_sha256:d.source_binding_sha256,parameters_sha256:d.parameters_sha256});
 // Normal two-plot workflow: volcano occupies capacity while heatmap is refused before consumption.
 const a=await setupRead(t);await classified(a);a.d.by('data-de-volcano-control','generate').click();await until(()=>a.allSubmitted.volcano.length===1&&!a.actor.view().busy);assert.equal(a.actor.view().volcanoRender.phase,'queued');
 const volcano=stored(a,'volcano'),actor=a.o.parentMetadata.created_by,scope=hash({domain:'cyomics/heatmap-render/request-recovery/v1',actor_id:actor}),recovery=createHeatmapRenderRecovery(a.storage);
 const other={v:1,request_id:id(87),context:{...contextOf(a.heatmapDescriptor),derived_version_id:id(86),derived_metadata_sha256:'3'.repeat(64)},render_id:null,binding_sha256:null};recovery.put(actor,scope,other);const otherBytes=stored(a).text;
 a.renderMode('busy');await clickGenerate(a);assert.equal(a.actor.view().heatmapRender.phase,'capacity_busy');assert.equal(a.actor.view().heatmapRender.has_reference,false);assert.equal(a.actor.view().heatmapRender.can_generate,true);assert.match(a.d.by('data-de-heatmap-render-state','status').textContent,/计算资源忙碌/);
 assert.equal(stored(a).text,otherBytes,'remove exactly this intent, preserving another heatmap reference');assert.equal(stored(a,'volcano').text,volcano.text);assert.equal(a.submitted.length,1);assert.equal(a.queried.length,0);await flush();assert.equal(a.submitted.length,1,'no automatic retry or new POST');
 const refused=a.submitted[0];a.renderMode('created');button(a,'generate').click();await until(()=>a.submitted.length===2&&!a.actor.view().busy);assert.notEqual(a.submitted[1],refused,'a new request is created only by the later explicit click');assert.equal(a.actor.view().heatmapRender.phase,'queued');await showGenerated(a);assert.equal(a.actor.view().heatmap.phase,'ready');assert.deepEqual(a.queried,[a.submitted[1]]);assert.equal(stored(a,'volcano').text,volcano.text);
 // An anchored admission and even a GET busy error never enter POST-only cleanup.
 const anchored=JSON.parse(stored(a).text).items.find(r=>r.request_id===a.submitted[1]);assert.notEqual(anchored.render_id,null);const anchorsBefore=stored(a).text;
 assert.throws(()=>recovery.removeUnconsumed(actor,scope,anchored,()=>{}));assert.equal(stored(a).text,anchorsBefore);
 a.renderMode('busy-status');await check(a,'running');assert.equal(a.actor.view().heatmapRender.phase,'unknown');assert.equal(stored(a).text,anchorsBefore);assert.equal(await a.actor.generateHeatmap(),false);assert.equal(a.submitted.length,2);
 // Ambiguous 504 and malformed busy replies retain the original unanchored intent.
 for(const mode of ['unknown','busy-extra']){
  const b=await setupRead(t);await classified(b);b.renderMode(mode);await clickGenerate(b);assert.equal(b.actor.view().heatmapRender.phase,'unknown');const before=stored(b),env=JSON.parse(before.text),ref=env.items[0],r=createHeatmapRenderRecovery(b.storage);
  assert.equal(ref.render_id,null);assert.equal(ref.binding_sha256,null);assert.equal(ref.request_id,b.submitted[0]);assert.equal(await b.actor.generateHeatmap(),false);assert.equal(b.submitted.length,1);
  for(const changed of [{...ref,request_id:id(88)},{...ref,context:{...ref.context,parameters_sha256:'4'.repeat(64)}}])assert.throws(()=>r.removeUnconsumed(ref.context.actor_id,env.scope,changed,()=>{}));assert.equal(stored(b).text,before.text);
 }
 // A late exact busy response after classification cancellation must not erase its persisted hint.
 const c=await setupRead(t);await classified(c);c.renderMode('hold');button(c,'generate').click();await until(()=>c.renderHeld());const late=c.renderHeld(),lateHint=stored(c).text;await c.actor.clearClassification();late.call.deliver({error:{code:'r_heatmap_capacity_busy'}},409);await flush();assert.equal(stored(c).text,lateHint);assert.equal(c.actor.view().classification.phase,'idle');await classified(c);assert.equal(c.actor.view().heatmapRender.phase,'recovered');assert.equal(await c.actor.generateHeatmap(),false);assert.equal(c.submitted.length,1);
 // If the narrowly scoped rewrite cannot be confirmed, keep the current Owner blocked.
 const d=await setupRead(t);await classified(d);const originalSet=d.storage.setItem;d.storage.setItem=(key,value)=>{if(key.startsWith('cyomics:heatmap-render:')&&JSON.parse(value).items.length===0)throw Error('synthetic recovery write failure');originalSet(key,value);};d.renderMode('busy');await clickGenerate(d);
 assert.equal(d.actor.view().heatmapRender.recovery_status,'blocked');assert.equal(d.actor.view().heatmapRender.has_reference,true);assert.equal(d.actor.view().heatmapRender.can_generate,false);assert.equal(JSON.parse(stored(d).text).items[0].request_id,d.submitted[0]);assert.equal(await d.actor.generateHeatmap(),false);assert.equal(d.submitted.length,1);
 t.diagnostic('HM-FE-001 only: one finite new target, synthetic session/BFF/native wire and event DOM. Prior parent/children are excluded by test-name-pattern. No real backend/capacity/claim/R/browser operation; no automatic POST, no server claim cleanup.');
});
